    int  SendPlayerToServerInput_SwitchWeapons(unsigned long long objId, int bSwap);
    // Returns success without sending while a conversation is already running.
    int  SendPlayerToServerInput_Dialog(unsigned long long objId);
    int  SendPlayerToServerInput_CancelDisguise(unsigned long long objId);
    int  SendPlayerToServerInput_Attack(unsigned long long objId,
                                        unsigned short a);
    int  SendPlayerToServerInput_ToggleMode(unsigned char mode,
                                            unsigned long long objId);
    int  SendPlayerToServerInput_UseFeat(unsigned short nFeat, unsigned short nSubFeat,
                                         unsigned long long objId);
    int  SendPlayerToServerInventory_Pickup(unsigned long long objId,
                                            unsigned long long objId2);
    int  SendPlayerToServerInput_CastSpellLikeAbility(unsigned int nSpellId,
                                                      unsigned char nSubType, const Vector& pos,
                                                      unsigned long long objId);
    int  SendPlayerToServerInput_GiveItem(unsigned long long giverId, unsigned long long itemId,
                                          unsigned long long objId, int count);
    int  SendPlayerToServerInventory_Drop(unsigned long long itemId, float x, float y,
                                          float z);

    int SendPlayerToServerStatus_RequestStatus();

    int SendPlayerToServerShutDownServer(int bShutDown);
    int SendPlayerToServerLogin_CharacterResponse(int bAccept);
    int SendPlayerToServerInput_GetObjectDebugInfo(unsigned long long objId);
    int SendPlayerToServerMapPinRemoved(int nPin);
    int SendPlayerToServerInventory_LearnScroll(unsigned long long objId);
    int SendPlayerToServerInput_SetPauseRequest(int bPause);
    int SendPlayerToServer_RequestCharacterListUpdate(unsigned char nLocation,
                                                      const CResRef& resRef);
    int SendPlayerToServerInput_MergeItem(unsigned long long itemId,
                                          unsigned long long targetId);
    int SendPlayerToServerInput_SplitItem(unsigned long long itemId,
                                          int nCount);
    int SendPlayerToServerJournalMessage_RequestDelete(int nEntry,
                                                       int bDelete);
    int SendPlayerToServerInput_CancelAction(unsigned short nActionId,
                                             unsigned short nGroupId);

    // The appearance-update quartet shares one category and sub-opcode and is told apart on the
