    // own tags, 'V' and 'L'.
    int SendPlayerToServerUpdate_AppearanceHeadVariation(unsigned long long objId,
                                                         unsigned char nVariation);
    int SendPlayerToServerUpdate_AppearanceGender(unsigned long long objId,
                                                  unsigned char nGender);
    int SendPlayerToServerUpdate_AppearanceRace(unsigned long long objId,
                                                unsigned short nRace);
    int SendPlayerToServerUpdate_AppearancePhenoType(unsigned long long objId,
                                                     unsigned char nPhenoType);

    // Raises the item's own client-side "sale pending" latch after the message has been built.
    int SendPlayerToServerStore_RequestSell(unsigned long long itemId);
    // Ships only the x and y components; a turn on the spot has no vertical part.
    int SendPlayerToServerInput_TurnOnSpot(const Vector& dir);
    int SendPlayerToServerModule_SaveGame(unsigned int nSlot, const CExoString& sName,
                                          const CExoString& sDesc);
    int SendPlayerToServerModule_LoadGame(unsigned int nSlot, const CExoString& sName,
                                          const CExoString& sDesc);
    int SendPlayerToServerSpellUnMemorize(unsigned char nClassSlot, unsigned char nLevel,
                                          unsigned char nSlot);

    int SendPlayerToServerUpdate_AppearancePartVariation(unsigned long long objId,
                                                         unsigned char nPart,
                                                         unsigned char nVariation);
    int SendPlayerToServerUpdate_AppearancePLTColor(unsigned long long objId, unsigned char nLayer,
                                                    unsigned char nColor);

    // The quickbar pair shares a category/sub-opcode and a hardcoded payload type tag, 2 for a
    // spell and 44 for a spell-like ability.
    int SendPlayerToServerGuiQuickbar_SetButton_SpellLikeAbility(unsigned char nButton,
                                                                 unsigned int nSpellId,
                                                                 unsigned char nSubType);
    // The slot and class parameters ship in the reverse of their declared order.
    int SendPlayerToServerGuiQuickbar_SetButton_Spell(unsigned char nButton,
                                                      unsigned char nSubType,
                                                      unsigned int nSpellId, unsigned char nClass,
                                                      unsigned char nSlot);

    // Both pick their sub-opcode at run time from the same flag; neither flag reaches the payload.
    int SendPlayerToServerLogin_LoginLocalCharacter(unsigned char* pData, unsigned int nLen,
                                                    int bJoin);
    // This overload does the work; it loads the character off disk and forwards the raw bytes.
    int SendPlayerToServerLogin_LoginLocalCharacter(const CResRef& resRef, int bJoin);
    int SendPlayerToServerLogin_LoginServerCharacter(const CResRef& resRef, int bJoin,
                                                     int bCreate);

    int SendPlayerToServerStore_RequestBuy(unsigned long long itemId, unsigned char nStack,
                                           unsigned char nSlot);
    int SendPlayerToServerJournalMessage_RequestAdd(const CExoString& sTitle,
                                                    const CExoString& sText);
    int SendPlayerToServerCheat_PlayVisualEffect(unsigned long long objId, unsigned short nEffect,
                                                 float fDuration, unsigned long long targetId,
                                                 unsigned char nType);
    int SendPlayerToServerSpellMemorize(unsigned char nClassSlot, unsigned int nSpellId,
                                        unsigned char nLevel, unsigned char nSlot,
                                        unsigned char nMeta);
    int SendPlayerToServerMapPinAdded(const Vector& pos,
                                      const CExoString& sNote);
    // The heading ships at twelve bits, and only the x and y components of the direction.
    int SendPlayerToServerInput_DriveControl(const Vector& dir, unsigned short nHeading,
                                             unsigned char a, unsigned char b);

    int SendPlayerToServerGuiQuickbar_SetButton_Item(unsigned char nButton,
                                                     unsigned long long itemId, int nCount,
                                                     unsigned long long targetId);
