    int SendPlayerToServerGold_TransferGold(unsigned long long objId, const Vector& pos,
                                            int nAmount);
    int SendPlayerToServerMapPinChanged(const Vector& pos, const CExoString& sNote,
                                        int nPin);

    // The cheat "add" trio rides the same appearance channel as the Update_Appearance* members,
    // with its own tag letters: 'C', 'M', 'A'.
    int SendPlayerToServerCreature_Add(unsigned long long objId, const Vector& pos,
                                       const CExoString& sResRef);
    int SendPlayerToServerParty_Add(unsigned long long objId, const Vector& pos,
                                    const CExoString& sResRef);
    int SendPlayerToServerItem_Add(unsigned long long objId, const Vector& pos,
                                   const CResRef& resRef, unsigned char a, unsigned char b,
                                   unsigned char c);

    // The position arrives as three loose floats, not as a Vector.
    int SendPlayerToServerInput_WalkToWayPoint(unsigned long long objId, float x, float y, float z,
                                               unsigned char a, int b, int c, unsigned char d,
                                               unsigned long long objId2);

    // The spell-cast packers ship a bit-mask byte naming which optional fields follow, and write
    // each field under the same test that raised its bit: target object id, target point, and
    // (Input_CastSpell only) its own argument. Both Input_ members offset the shipped z by
    // 0.3f; Cheat_CastSpell does not.
    int SendPlayerToServerCheat_CastSpell(unsigned int nSpellId, const Vector& pos,
                                          unsigned long long objId);

    // The party action picks only the sub-opcode, and its case 2 has no arm, so it returns 0; case
    // 8 discards its payload and sends the empty message instead.
    int SendPlayerToServerParty_Action(unsigned long long objId,
                                       int nAction);

    // Journal-screen open/close notifications, forwarded from CSWCJournal.
    int SendPlayerToServerJournalMessage_QuestScreenOpen();
    int SendPlayerToServerJournalMessage_QuestScreenClosed();

    // The inbound reader primitives, the client-specific complements to CSWMessage's Read* set.
    void WriteOBJECTIDClient(unsigned long long objId);
    unsigned long long ReadOBJECTIDClient();
    CExoString ReadCExoLocStringClient();
    // In the two-argument overload, the multi-language chat channel's locstring ships a default
    // sound resref and a bubble duration alongside the text, so the resref and the duration come
    // back through out-parameters.
    CExoString ReadCExoLocStringClient(CResRef& rSound, float* pfDuration);

    // Inbound handlers: "the server told us something, apply it on the client". Reached through the
    // category dispatchers below, or from another handler.
    //
    // Most share one body: test the read overflow, read the payload, test the overflow again, act
    // on client state, return 1. Where nothing follows the last test it collapses to a single
    // underflow test. A handful are stubs that return a constant, because the engine's dialog and
    // examine paths moved client-side and the message hooks were left behind.

    // The top-level per-category entry points and the sub-opcode dispatchers under them.
    int HandleServerToPlayerDialog(unsigned char nType);
    int HandleServerToPlayerCharacterList(unsigned char nType);
    int HandleServerToPlayerCamera(unsigned char nType);
    int HandleServerToPlayerArea(unsigned char nType);
    int HandleServerToPlayerQuickChat(unsigned char nType);
    int HandleServerToPlayerPlayModuleCharacterList(unsigned char nType);
    int HandleServerToPlayerDebugInfo_Area(unsigned long long objId);

    // The dialog-refresh hooks CGuiInGame drives; all five are constant-return stubs.
    int UpdatePlayerDialog(class CGuiInGame* pGui);
    int UpdatePlayerReplies(class CGuiInGame* pGui);
    int UpdatePlayerReplyChosen(class CGuiInGame* pGui);
    int UpdateModels(class CGuiInGame* pGui);
    int UpdateStuntAnimations(class CGuiInGame* pGui);

