    // the client to log in. Sub-opcode 1 replies with a literal console command string rather than
    // a packed message.
    int HandleServerToPlayerServerStatus(unsigned char nType);

    // On the roster channel, 1 replaces the whole list (a count byte and that many entry blocks), 2
    // appends one entry, 3 removes one entry by player id. Sub-opcode 2 ships no count byte; the
    // shared entry loop is entered with a hardcoded count of 1.
    int HandleServerToPlayerPlayerList(unsigned char nType);

    // The module channel. Sub-opcodes 2, 4, 5, 7 and 9 have no arm, and 6's arm is empty.
    int HandleServerToPlayerModule(unsigned char nType);
    int HandleServerToPlayerExportReply();

    // The game-object update channel, the busiest inbound channel. Sub-opcode 1 runs a loop over
    // the rest of the message, each iteration reading a tag byte ('A' to 'W', with only A, D, G,
    // I, P, U and W live) that selects the update kind.
    int HandleServerToPlayerGameObjectUpdate(unsigned char nType);
    int HandleServerToPlayerCreatureUpdate_ControlObject(unsigned long long objId);
    int HandleServerToPlayerCreatureUpdate_VisEffect();
    int HandleServerToPlayerItemUpdate_DestroyItem();
    int HandleServerToPlayerItemScript_Add();
    int HandleServerToPlayerUpdate_PlayerInfo();
    int HandleServerToPlayerUpdate_Update();
    // The only update leaf reached without going through the shared generic-object walker first,
    // which dispatches straight to it for creatures.
    int HandleServerToPlayerCreatureUpdate_Update(unsigned long long objId,
                                                  unsigned int nSize);

    // On the character-download channel, sub-opcode 2 ships the save file as a raw blob (a length
    // and that many bytes), sub-opcode 3 ships a path string, and both hand their bytes to the same
    // setter.
    int HandleServerToPlayerCharacterDownload(unsigned char nType);

    // The loading-bar channel begins a bar, reports progress, and ends it. Every arm short-circuits
